# ══════════════════════════════════════════════════
#  PATTERN 6: REPOSITORY
#  Separate data access from business logic
# ══════════════════════════════════════════════════
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import List, Optional
from datetime import datetime

# ─── Domain Entities (pure business objects — no DB code!) ───
@dataclass
class Customer:
    customer_id : str
    name        : str
    email       : str
    tier        : str = "bronze"
    created_at  : str = field(default_factory=lambda: datetime.now().isoformat())
    is_active   : bool = True

    def upgrade_tier(self, new_tier: str):
        valid_tiers = ["bronze", "silver", "gold", "platinum", "vip"]
        if new_tier not in valid_tiers:
            raise ValueError(f"Invalid tier: {new_tier}")
        old_tier  = self.tier
        self.tier = new_tier
        print(f"  ⬆️  {self.name}: {old_tier} → {new_tier}")

@dataclass
class Product:
    product_id  : str
    name        : str
    price       : float
    stock       : int
    category    : str
    is_available: bool = True

    def reduce_stock(self, qty: int):
        if qty > self.stock:
            raise ValueError(f"Insufficient stock: {self.stock} < {qty}")
        self.stock -= qty

    def add_stock(self, qty: int):
        self.stock += qty

@dataclass
class Order:
    order_id   : str
    customer_id: str
    items      : List[dict] = field(default_factory=list)
    status     : str        = "pending"
    total      : float      = 0.0
    created_at : str        = field(default_factory=lambda: datetime.now().isoformat())

    def add_item(self, product_id, name, qty, unit_price):
        self.items.append({
            "product_id" : product_id,
            "name"       : name,
            "qty"        : qty,
            "unit_price" : unit_price,
            "subtotal"   : qty * unit_price
        })
        self.total = sum(i['subtotal'] for i in self.items)

# ─── Repository Interfaces (Abstractions) ───
class CustomerRepository(ABC):
    @abstractmethod
    def save(self, customer: Customer) -> Customer: pass

    @abstractmethod
    def find_by_id(self, customer_id: str) -> Optional[Customer]: pass

    @abstractmethod
    def find_by_email(self, email: str) -> Optional[Customer]: pass

    @abstractmethod
    def find_all(self) -> List[Customer]: pass

    @abstractmethod
    def find_by_tier(self, tier: str) -> List[Customer]: pass

    @abstractmethod
    def delete(self, customer_id: str) -> bool: pass

    def exists(self, customer_id: str) -> bool:
        return self.find_by_id(customer_id) is not None

class ProductRepository(ABC):
    @abstractmethod
    def save(self, product: Product) -> Product: pass

    @abstractmethod
    def find_by_id(self, product_id: str) -> Optional[Product]: pass

    @abstractmethod
    def find_by_category(self, category: str) -> List[Product]: pass

    @abstractmethod
    def find_available(self) -> List[Product]: pass

    @abstractmethod
    def find_all(self) -> List[Product]: pass

    def find_in_stock(self) -> List[Product]:
        return [p for p in self.find_all() if p.stock > 0]

class OrderRepository(ABC):
    @abstractmethod
    def save(self, order: Order) -> Order: pass

    @abstractmethod
    def find_by_id(self, order_id: str) -> Optional[Order]: pass

    @abstractmethod
    def find_by_customer(self, customer_id: str) -> List[Order]: pass

    @abstractmethod
    def find_by_status(self, status: str) -> List[Order]: pass

    @abstractmethod
    def find_all(self) -> List[Order]: pass

# ─── In-Memory Repository (for testing + development) ───
class InMemoryCustomerRepository(CustomerRepository):
    def __init__(self):
        self._store: dict = {}

    def save(self, customer):
        self._store[customer.customer_id] = customer
        print(f"  💾 [MEM] Saved customer: {customer.customer_id}")
        return customer

    def find_by_id(self, customer_id):
        return self._store.get(customer_id)

    def find_by_email(self, email):
        return next((c for c in self._store.values()
                     if c.email == email), None)

    def find_all(self):
        return list(self._store.values())

    def find_by_tier(self, tier):
        return [c for c in self._store.values() if c.tier == tier]

    def delete(self, customer_id):
        return self._store.pop(customer_id, None) is not None

class InMemoryProductRepository(ProductRepository):
    def __init__(self):
        self._store: dict = {}

    def save(self, product):
        self._store[product.product_id] = product
        return product

    def find_by_id(self, product_id):
        return self._store.get(product_id)

    def find_by_category(self, category):
        return [p for p in self._store.values() if p.category == category]

    def find_available(self):
        return [p for p in self._store.values() if p.is_available]

    def find_all(self):
        return list(self._store.values())

class InMemoryOrderRepository(OrderRepository):
    def __init__(self):
        self._store: dict = {}

    def save(self, order):
        self._store[order.order_id] = order
        print(f"  💾 [MEM] Saved order: {order.order_id}")
        return order

    def find_by_id(self, order_id):
        return self._store.get(order_id)

    def find_by_customer(self, customer_id):
        return [o for o in self._store.values()
                if o.customer_id == customer_id]

    def find_by_status(self, status):
        return [o for o in self._store.values() if o.status == status]

    def find_all(self):
        return list(self._store.values())

# ─── Business Service (pure business logic, zero DB code!) ───
class OrderService:
