**What this code covers**

- YOUR system's standard interface
- Returns: {success, transaction_id, message}
- Old in-house system written 10 years ago.
- Note: takes PAISE not rupees!
- Make incompatible interfaces work together
- EXAMPLE 1: Payment Gateway Adapter
- (Making legacy + third-party gateways work
- With your modern interface)

**Defines:** `ModernPaymentGateway`, `LegacyPaymentSystem`, `RazorpaySDK`, `LegacyPaymentAdapter`, `RazorpayAdapter`, `CheckoutService`, `DataSource`, `CSVDataSource`, `JSONDataSource`, `CSVAdapter`

### 📖 Explanation:
```
PROBLEM:  You have two classes that should work together,
          but their interfaces are INCOMPATIBLE.
          You can't change either class (legacy code, third-party).

SOLUTION: Create an ADAPTER that wraps one class and translates
          its interface into what the other class expects.

ANALOGY:  POWER ADAPTER / TRAVEL PLUG
  Your Indian laptop charger (3-pin, 230V)
  US wall socket (2-pin, 110V)

  They're INCOMPATIBLE. You can't plug one into the other directly.
  A TRAVEL ADAPTER sits in between:
  → Accepts Indian plug  (existing interface)
  → Fits into US socket  (target interface)
  → Neither plug nor socket changes!

TWO TYPES:
  Object Adapter  → Wraps object via COMPOSITION (preferred)
  Class Adapter   → Inherits from both (multiple inheritance)
```

```python name=adapter_pattern.py
# ══════════════════════════════════════════════════
#  PATTERN 7: ADAPTER
#  Make incompatible interfaces work together
# ══════════════════════════════════════════════════
from abc import ABC, abstractmethod
from typing import List, Dict, Any

# ══════════════════════════════════════════════════
#  EXAMPLE 1: Payment Gateway Adapter
#  (Making legacy + third-party gateways work
#   with your modern interface)
# ══════════════════════════════════════════════════

# ─── Target Interface (what YOUR system expects) ───
class ModernPaymentGateway(ABC):
    """YOUR system's standard interface"""

    @abstractmethod
    def charge(self, amount_rupees: float,
               card_number: str, cvv: str) -> dict:
        """Returns: {success, transaction_id, message}"""
        pass

    @abstractmethod
    def refund(self, transaction_id: str,
               amount_rupees: float) -> dict:
        pass

    @abstractmethod
    def get_transaction_status(self,
                               transaction_id: str) -> str:
        pass

# ─── Adaptee 1: Legacy in-house payment system ───
class LegacyPaymentSystem:
    """
    Old in-house system written 10 years ago.
    Cannot be modified — too many dependencies.
    Has completely different interface.
    """

    def make_payment(self, amt_paise: int,
                     card_no: str, security_code: str):
        """Note: takes PAISE not rupees!"""
        print(f"  💳 [LEGACY] Payment of ₹{amt_paise/100:.2f} "
              f"on card ending {card_no[-4:]}")
        return {
            "status_code"  : "00",    # 00 = success in legacy system
            "ref_number"   : f"LEG{id(self)}",
            "error_message": ""
        }

    def reverse_payment(self, ref_number: str,
                        amt_paise: int):
        print(f"  ↩️  [LEGACY] Reversing ₹{amt_paise/100:.2f} "
              f"ref={ref_number}")
        return {"status_code": "00", "ref_number": ref_number}

    def query_payment(self, ref_number: str):
        # Returns legacy status codes: 00=success, 01=pending, 99=failed
        return {"status_code": "00", "ref_number": ref_number}

# ─── Adaptee 2: Third-party Razorpay SDK ───
class RazorpaySDK:
    """
    Third-party SDK — can't modify.
    Different method names, different data formats.
    """

    def initiate_charge(self, amount: float, currency: str,
                        payment_method: dict) -> dict:
        print(f"  💳 [RAZORPAY] Charging {currency} {amount:.2f}")
        return {
            "razorpay_payment_id": f"pay_{id(self)}",
            "razorpay_order_id"  : f"order_{id(self)}",
            "status"             : "captured"   # razorpay status
        }

    def create_refund(self, payment_id: str,
                      amount: float) -> dict:
        print(f"  ↩️  [RAZORPAY] Refunding {amount:.2f} "
              f"for {payment_id}")
        return {
            "id"    : f"rfnd_{id(self)}",
            "status": "processed"
        }

    def fetch_payment(self, payment_id: str) -> dict:
        return {
            "id"    : payment_id,
            "status": "captured",   # razorpay-specific status
            "amount": 50000         # in paise!
        }

# ─── Adapter 1: Legacy → Modern ───
class LegacyPaymentAdapter(ModernPaymentGateway):
    """
    Adapts LegacyPaymentSystem to ModernPaymentGateway.
    Translates: rupees↔paise, status codes↔strings, method names
    """

    # Legacy status code → Modern status string
    STATUS_MAP = {
        "00": "SUCCESS",
        "01": "PENDING",
        "99": "FAILED",
    }

    def __init__(self, legacy_system: LegacyPaymentSystem):
        self._legacy = legacy_system   # COMPOSITION — wrap it!

    def charge(self, amount_rupees, card_number, cvv) -> dict:
        # Translate: rupees → paise
        amount_paise = int(amount_rupees * 100)

        result = self._legacy.make_payment(
            amount_paise, card_number, cvv
        )

        # Translate: legacy response → modern response
        return {
            "success"       : result["status_code"] == "00",
            "transaction_id": result["ref_number"],
            "message"       : result["error_message"] or "Payment successful"
        }

    def refund(self, transaction_id, amount_rupees) -> dict:
        amount_paise = int(amount_rupees * 100)
        result = self._legacy.reverse_payment(
            transaction_id, amount_paise
        )
        return {
            "success"       : result["status_code"] == "00",
            "transaction_id": result["ref_number"],
            "message"       : "Refund processed"
        }

    def get_transaction_status(self, transaction_id) -> str:
        result = self._legacy.query_payment(transaction_id)
        return self.STATUS_MAP.get(result["status_code"], "UNKNOWN")

# ─── Adapter 2: Razorpay → Modern ───
class RazorpayAdapter(ModernPaymentGateway):
    """Adapts Razorpay SDK to ModernPaymentGateway interface"""

    RAZORPAY_STATUS_MAP = {
        "captured" : "SUCCESS",
        "authorized": "PENDING",
        "refunded" : "REFUNDED",
        "failed"   : "FAILED",
    }

    def __init__(self, razorpay_sdk: RazorpaySDK):
        self._rzp = razorpay_sdk

    def charge(self, amount_rupees, card_number, cvv) -> dict:
        # Razorpay needs a payment_method dict
        payment_method = {
            "type"      : "card",
            "card_number": card_number,
            "cvv"        : cvv
        }
        result = self._rzp.initiate_charge(
            amount=amount_rupees,
            currency="INR",
            payment_method=payment_method
        )
        return {
            "success"       : result["status"] == "captured",
            "transaction_id": result["razorpay_payment_id"],
            "message"       : f"Razorpay: {result['status']}"
        }

    def refund(self, transaction_id, amount_rupees) -> dict:
        result = self._rzp.create_refund(transaction_id, amount_rupees)
        return {
            "success"       : result["status"] == "processed",
            "transaction_id": result["id"],
            "message"       : "Razorpay refund processed"
        }

    def get_transaction_status(self, transaction_id) -> str:
        result = self._rzp.fetch_payment(transaction_id)
        return self.RAZORPAY_STATUS_MAP.get(result["status"], "UNKNOWN")

# ─── Your system uses ModernPaymentGateway — works with BOTH! ───
class CheckoutService:
    """
    Uses ModernPaymentGateway interface.
    Has NO IDEA whether it's talking to Legacy or Razorpay.
    Completely insulated from third-party details.
    """

    def __init__(self, gateway: ModernPaymentGateway):
        self._gateway = gateway

    def process_payment(self, amount: float,
                        card: str, cvv: str) -> str:
        print(f"\n  🛒 Processing payment of ₹{amount:,.2f}")
        result = self._gateway.charge(amount, card, cvv)

        if result['success']:
            txn_id = result['transaction_id']
            status = self._gateway.get_transaction_status(txn_id)
            print(f"  ✅ Payment success! TXN: {txn_id} | Status: {status}")
            return txn_id
        else:
            raise RuntimeError(f"Payment failed: {result['message']}")

    def process_refund(self, txn_id: str, amount: float):
        print(f"\n  ↩️  Processing refund ₹{amount:,.2f}")
        result = self._gateway.refund(txn_id, amount)
        print(f"  {'✅' if result['success'] else '❌'} "
              f"Refund: {result['message']}")

# ─── Testing: Same CheckoutService with different adapters ───
print("=" * 55)
print("  ADAPTER PATTERN: Payment Gateway")
print("=" * 55)

# With Legacy system
print("\n--- Using Legacy Payment System ---")
legacy   = LegacyPaymentSystem()
checkout = CheckoutService(LegacyPaymentAdapter(legacy))
txn1     = checkout.process_payment(1500.0, "4111111111111234", "123")
checkout.process_refund(txn1, 500.0)

# With Razorpay — same CheckoutService!
print("\n--- Using Razorpay ---")
razorpay = RazorpaySDK()
checkout = CheckoutService(RazorpayAdapter(razorpay))
txn2     = checkout.process_payment(2500.0, "5500000000000004", "456")
checkout.process_refund(txn2, 250.0)

# ══════════════════════════════════════════════════
#  EXAMPLE 2: Data Source Adapter
#  (Making CSV, JSON, XML look like a Database)
# ══════════════════════════════════════════════════

class DataSource(ABC):
    """Target interface — all data sources look the same"""
    @abstractmethod
    def get_records(self) -> List[Dict]: pass

    @abstractmethod
    def count(self) -> int: pass

    @abstractmethod
    def find(self, field: str, value: Any) -> List[Dict]: pass

class CSVDataSource:
    """Existing CSV reader — different interface"""
    def __init__(self, data):
        self._rows = data

    def read_all_rows(self) -> List[List]: return self._rows
    def get_row_count(self) -> int: return len(self._rows)
    def filter_rows(self, col_idx: int, val: str) -> List[List]:
        return [r for r in self._rows if len(r) > col_idx and r[col_idx] == val]

class JSONDataSource:
    """Existing JSON reader — different interface"""
    def __init__(self, data):
        self._data = data

    def fetch_all(self) -> List[Dict]: return self._data
    def total_items(self) -> int: return len(self._data)
    def search(self, key: str, val: Any) -> List[Dict]:
        return [d for d in self._data if d.get(key) == val]

class CSVAdapter(DataSource):
    """Adapts CSVDataSource to DataSource interface"""
    COLUMNS = ['id', 'name', 'email', 'city']

    def __init__(self, csv: CSVDataSource):
        self._csv = csv

    def get_records(self) -> List[Dict]:
        return [
            dict(zip(self.COLUMNS, row))
            for row in self._csv.read_all_rows()
        ]

    def count(self) -> int:
        return self._csv.get_row_count()

    def find(self, field, value) -> List[Dict]:
        col_idx = self.COLUMNS.index(field) if field in self.COLUMNS else -1
        if col_idx < 0: return []
        rows = self._csv.filter_rows(col_idx, str(value))
        return [dict(zip(self.COLUMNS, row)) for row in rows]

class JSONAdapter(DataSource):
    """Adapts JSONDataSource to DataSource interface"""
    def __init__(self, json_src: JSONDataSource):
        self._json = json_src

    def get_records(self) -> List[Dict]:
        return self._json.fetch_all()

    def count(self) -> int:
        return self._json.total_items()

    def find(self, field, value) -> List[Dict]:
        return self._json.search(field, value)

def analyze_data(source: DataSource, source_name: str):
    """Works with ANY DataSource — CSV, JSON, DB, API"""
    print(f"\n  📊 Analyzing: {source_name}")
    print(f"  Total records : {source.count()}")
    all_records = source.get_records()
    if all_records:
        print(f"  First record  : {all_records[0]}")
    mumbai = source.find('city', 'Mumbai')
    print(f"  Mumbai users  : {len(mumbai)}")

# Test both adapters with same function
